function fetching () {
  return async (dispatch) => {
    dispatch({ type: types.AGENTS_FETCHING });
  };
}

const DEFAULT_RUN_ERROR_MESSAGE = 'There was an error, please try again.';

const flattenErrorValue = (value) => {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(flattenErrorValue).filter(Boolean).join(', ');
  if (value && typeof value === 'object') return Object.values(value).map(flattenErrorValue).filter(Boolean).join(', ');
  return '';
};

function buildRunErrorMessage (error, fallback = DEFAULT_RUN_ERROR_MESSAGE) {
  const { status, limits, ...rest } = error || {};
  return flattenErrorValue(rest.message || rest) || fallback;
}

function dispatchRunError (dispatch, e) {
  dispatch({ type: types.AGENTS_RUN_FAILED });
  dispatch(setError(buildRunErrorMessage(e)));
}

function somethingWentWrong (error) {
  return async (dispatch) => {
    dispatch({ type: types.AGENTS_FAIL, errorMessage: buildRunErrorMessage(error), errors: error });
  };
}

export function getUserAgents () {
  return async (dispatch, getState) => {
    const state = getState();
    try {
      dispatch(fetching());
      const queryParam = selectQueryParam('agents', state);
      const response = await api.agents.fetchUserAgents(queryParam);
      const userAgents = response.rows.map((el) => el);
      dispatch({ type: types.AGENTS_GET_USER_AGENTS, userAgents, count: response.count });
    } catch (e) {
      dispatch(somethingWentWrong(e));
    }
  };
}

