export function runUserAgentTool (toolName, toolParams, toolId) {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const agentId = selectTriggerAgentId(state);
      const workspaces = selectTriggerAgentWs(state, toolId);
      const min_severity = selectTriggerMinSeverity(state, toolId);
      const max_severity = selectTriggerMaxSeverity(state, toolId);
      const resolveHostname = selectTriggerResolveHostname(state, toolId);

      dispatch(fetching());

      const toolParamsClone = cloneDeep(toolParams);
      // sanitize args using executor metadata if available
      const executors = selectTriggerAgentTools(state);
      const executor = executors.find((t) => t.id === toolId) || {};
      const paramsMeta = executor.parameters_metadata || {};
      const extraAllowed = [];
      const sanitizedArgs = sanitizeByMetadata(toolParamsClone, paramsMeta, extraAllowed);

      const payload = {
        min_severity,
        max_severity,
        resolve_hostname: resolveHostname,
        workspaces_names: workspaces,
        executor_data: {
          agent_id: agentId,
          executor: toolName,
          args: sanitizedArgs
        },

        vuln_tag: toolParams.vuln_tag,
        service_tag: toolParams.service_tag,
        host_tag: toolParams.host_tag
      };
      await api.agents.runUserAgentTool(agentId, payload);
      dispatch(trackEvent(CATEGORIES.agent, ACTIONS.runAgent.name, ACTIONS.runAgent.label, agentId));

      dispatch(getUserAgents());
      dispatch(closeModal(MODAL_RUN_USER_AGENT));
      dispatch({ type: types.AGENTS_SET_SUCCESS, message: `${toolName} has been started` });
      dispatch(setTagsEntity('assetsTags', false));
      dispatch(setTagsEntity('vulnsTags', false));
      dispatch(setTagsEntity('servicesTags', false));
    } catch (e) {
      dispatch(setError(buildRunErrorMessage(e)));
    }
  };
}

