export function runCloudAgent (args) {
  return async (dispatch, getState) => {
    try {
      const agentId = selectTriggerAgentId(getState());
      const workspaces = selectTriggerCloudAgentWs(getState());
      const min_severity = selectTriggerMinSeverity(getState());
      const max_severity = selectTriggerMaxSeverity(getState());
      const resolveHostname = selectTriggerResolveHostname(getState());
      const argsClone = cloneDeep(args);
      // sanitize cloud args by cloud agent params if available
      const state = getState();
      let cloudAgent = get(state, 'agents.selectedCloudAgent', null);
      if (!cloudAgent) {
        const cloudAgents = get(state, 'agents.cloudAgents', []);
        cloudAgent = cloudAgents.find((ca) => ca.id === agentId) || null;
      }
      const cloudParamsMeta = cloudAgent?.params || {};
      const sanitizedArgs = sanitizeByMetadata(argsClone, cloudParamsMeta, []);

      dispatch(fetching());
      const payload = {
        workspaces,
        args: sanitizedArgs,
        min_severity,
        max_severity,
        resolve_hostname: resolveHostname,
        host_tag: args.host_tag,
        vuln_tag: args.vuln_tag,
        service_tag: args.service_tag
      };

      await api.agents.runCloudAgent(agentId, payload);
      dispatch(trackEvent(CATEGORIES.cloudAgent, ACTIONS.runCloudAgent.name, ACTIONS.runCloudAgent.label, agentId));
      dispatch(getCloudAgents());
      dispatch(closeModal(MODAL_RUN_CLOUD_AGENT));
      dispatch(closeModal(MODAL_AGENT_DETAIL));
      dispatch({ type: types.AGENTS_SUCCESS });
    } catch (e) {
      dispatchRunError(dispatch, e);
    }
  };
}

export function runCloudAgentTool (wsSelected, toolParams, tags) {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const agentId = selectTriggerAgentId(state);
      const assetsTags = selectAssetsTags(state);
      const vulnsTags = selectVulnsTags(state);
      const servicesTags = selectServicesTags(state);
      dispatch(fetching());
      const workspaces = wsSelected.map(w => w.primary);
      const parsedTags = tags ? tags.split(',').map((t) => t.trim()) : [];
      const newTags = [...new Set(parsedTags)];

      const payload = {
        workspaces,
        args: toolParams,
        vuln_tag: vulnsTags ? newTags : [],
        service_tag: servicesTags ? newTags : [],
        host_tag: assetsTags ? newTags : []
      };

      await api.agents.runCloudAgent(agentId, payload);

      dispatch(getCloudAgents());
      dispatch(closeModal(MODAL_RUN_USER_AGENT));
      dispatch({ type: types.AGENTS_SUCCESS });
      dispatch(setTagsEntity('assetsTags', false));
      dispatch(setTagsEntity('vulnsTags', false));
      dispatch(setTagsEntity('servicesTags', false));
    } catch (e) {
      dispatchRunError(dispatch, e);
    }
  };
}

