export function removeSelectedAgents () {
  return async (dispatch, getState) => {
    try {
      const agentsSelected = selectAgentsSelected(getState());
      if (!agentsSelected.length) return;
      const [firstAgent] = agentsSelected;

      dispatch(fetching());

      const ids = agentsSelected.map((agent) => agent.id);
      await api.agents.removeAgents(ids);

      dispatch(trackEvent(CATEGORIES.agent, ACTIONS.deleteAgent.name, ACTIONS.deleteAgent.label, firstAgent.id));
      dispatch(getUserAgents());
      dispatch(unSelectAll());
    } catch (e) {
      dispatch(somethingWentWrong(e));
    }
  };
}

