export const saveAgentToolData = (id, data) => async (dispatch, getState) => {
  try {
    const state = getState();
    const workspaces = selectTriggerAgentWs(state, id);
    const min_severity = selectTriggerMinSeverity(state, id);
    const max_severity = selectTriggerMaxSeverity(state, id);
    const resolveHostname = selectTriggerResolveHostname(state, id);
    const assetsTags = selectAssetsTags(state);
    const vulnsTags = selectVulnsTags(state);
    const servicesTags = selectServicesTags(state);
    const agentId = selectTriggerAgentId(state);

    // Build parameters_data by whitelisting only fields defined in executor.parameters_metadata
    const executors = selectTriggerAgentTools(state);
    const executor = executors.find((t) => t.id === id) || {};
    const paramsMeta = executor.parameters_metadata || {};

    const extraAllowed = ['min_severity', 'max_severity', 'resolve_hostname', 'workspaces_names', 'vuln_tag', 'service_tag', 'host_tag'];
    const parameters_data = sanitizeByMetadata(data, paramsMeta, extraAllowed);

    // ensure we include/seal other UI-provided values (override if needed)
    parameters_data.min_severity = min_severity;
    parameters_data.max_severity = max_severity;
    parameters_data.resolve_hostname = resolveHostname;
    parameters_data.workspaces_names = workspaces;
    parameters_data.vuln_tag = vulnsTags.map((t) => t?.name ?? t);
    parameters_data.service_tag = servicesTags.map((t) => t?.name ?? t);
    parameters_data.host_tag = assetsTags.map((t) => t?.name ?? t);
    if (id) {
      await api.agents.saveToolData({ executor_id: id, parameters_data });
      dispatch({ type: types.SAVE_AGENT_TOOL_DATA_SUCCESS });
      dispatch(getAgent(agentId));
    }
  } catch (e) {
    dispatch(somethingWentWrong(e));
  }
};

