export function runAgentFromLogs () {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const executionSelected = selectAgentExecutionSelected(state);
      const type = selectAgentExecutionType(state);
      const agentId = get(executionSelected, '[0].agent_id', '');
      const executorData = get(executionSelected, '[0].parameters_data.executor_data', {});
      const workspacesCommands = get(executionSelected, '[0].parameters_data.workspaces_commands', []);

      const executors = selectTriggerAgentTools(state);
      const executor = executors.find((t) => t.name === executorData.executor || t.id === executorData.executor_id) || {};
      const paramsMeta = executor.parameters_metadata || {};
      const sanitizedArgs = Object.keys(paramsMeta).length ? sanitizeByMetadata(executorData.args || {}, paramsMeta, []) : (executorData.args || {});

      dispatch(fetching());

      const payload = {
        workspaces_names: workspacesCommands.map((e) => e.workspace_name),
        executor_data: {
          ...executorData,
          agent_id: agentId,
          args: sanitizedArgs
        }
      };

      await api.agents.runUserAgentTool(agentId, payload);

      dispatch(getAgentsExecutions(type));
      dispatch(closeModal(MODAL_RUN_USER_AGENT));
      dispatch({ type: types.AGENTS_SUCCESS });
    } catch (e) {
      dispatch(somethingWentWrong(e));
    }
  };
}

export function runCloudAgentFromLogs () {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const executionSelected = selectAgentExecutionSelected(state);
      const type = selectAgentExecutionType(state);
      const agentId = get(executionSelected, '[0].cloud_agent_id', '');
      const data = get(executionSelected, '[0].parameters_data.args', {});
      const workspaces = get(executionSelected, '[0].parameters_data.workspaces', []);

      let cloudAgent = get(state, 'agents.selectedCloudAgent', null);
      if (!cloudAgent || cloudAgent.id !== agentId) {
        const cloudAgents = get(state, 'agents.cloudAgents', []);
        cloudAgent = cloudAgents.find((ca) => ca.id === agentId) || cloudAgent;
      }
      const cloudParamsMeta = cloudAgent?.params || {};
      const sanitizedArgs = Object.keys(cloudParamsMeta).length ? sanitizeByMetadata(data, cloudParamsMeta, []) : (data || {});

      dispatch(fetching());
      const payload = {
        args: sanitizedArgs,
        workspaces
      };
      await api.agents.runCloudAgent(agentId, payload);

      dispatch(getAgentsExecutions(type));
      dispatch(closeModal(MODAL_RUN_USER_AGENT));
      dispatch({ type: types.AGENTS_SUCCESS });
    } catch (e) {
      dispatchRunError(dispatch, e);
    }
  };
}

