export function addTriggerCloudAgentWs (ws) {
  return (dispatch, getState) => {
    const addedWorkspaces = selectTriggerCloudAgentWs(getState());
    const allWorkspaces = selectActiveWorkspaces(getState());

    const newWs = allWorkspaces.find((workspace) => workspace.name === ws)?.name;
    if (newWs) {
      const newWorkspaces = [
        ...addedWorkspaces.filter((workspace) => workspace !== ws),
        newWs
      ];

      dispatch(setTriggerCloudAgentWs(newWorkspaces));
    }
  };
}

export function removeTriggerCloudAgentWs (ws) {
  return (dispatch, getState) => {
    const addedWorkspaces = selectTriggerCloudAgentWs(getState());
    const newWorkspaces = addedWorkspaces.filter((w) => w !== ws);
    dispatch(setTriggerCloudAgentWs(newWorkspaces));
  };
}

export const saveCloudAgent = (id, data) => async (dispatch, getState) => {
  try {
    const state = getState();
    const workspaces = selectTriggerCloudAgentWs(state);
    const min_severity = selectTriggerMinSeverity(state);
    const max_severity = selectTriggerMaxSeverity(state);
    const resolveHostname = selectTriggerResolveHostname(state);
    const assetsTags = selectAssetsTags(state);
    const vulnsTags = selectVulnsTags(state);
    const servicesTags = selectServicesTags(state);
    const agentId = selectTriggerAgentId(state);

    // Build parameters_data for cloud agent by whitelisting using cloud agent params
    let cloudAgent = get(state, 'agents.selectedCloudAgent', null);
    if (!cloudAgent || cloudAgent.id !== id) {
      const cloudAgents = get(state, 'agents.cloudAgents', []);
      cloudAgent = cloudAgents.find((ca) => ca.id === id) || cloudAgent;
    }
    const cloudParamsMeta = cloudAgent?.params || {};
    const extraCloudAllowed = ['min_severity', 'max_severity', 'resolve_hostname', 'workspaces', 'vuln_tag', 'service_tag', 'host_tag'];
    const parameters_data = sanitizeByMetadata(data, cloudParamsMeta, extraCloudAllowed);

    parameters_data.min_severity = min_severity;
    parameters_data.max_severity = max_severity;
    parameters_data.resolve_hostname = resolveHostname;
    parameters_data.workspaces = workspaces;
    parameters_data.vuln_tag = vulnsTags.map((t) => t?.name ?? t);
    parameters_data.service_tag = servicesTags.map((t) => t?.name ?? t);
    parameters_data.host_tag = assetsTags.map((t) => t?.name ?? t);

    await api.agents.saveCloudAgents({ cloud_agent_id: id, parameters_data });
    dispatch({ type: types.SAVE_AGENT_TOOL_DATA_SUCCESS });
    dispatch(getAgent(agentId));
  } catch (e) {
    dispatch(somethingWentWrong(e));
  }
};

export const setOrderByUserAgents = (sorting) => (dispatch) => {
  dispatch(setOrderBy('agents', sorting));
  dispatch(getUserAgents());
};

export const setOrderByCloudAgents = (sorting) => (dispatch) => {
  dispatch(setOrderBy('cloudAgents', sorting));
  dispatch(getCloudAgents());
};

export const setOrderByAgentsExecutions = (sorting = [], entity) => (dispatch) => {
  if (sorting.length > 0) dispatch(setOrderBy('agentExecutions', sorting));
  else dispatch(clearOrderBy('agentExecutions'));
  dispatch(getAgentsExecutions(entity));
};

export const setAgentsEntity = (entity) => {
  return async (dispatch) => {
    dispatch({ type: types.SET_AGENTS_ENTITY, entity });
  };
};

