// Same derived flags the legacy getColumns computed once per build.
const isDetailExtended = ({ showVulnDetail, currentBreakpoint }) => (showVulnDetail && currentBreakpoint === 'second');
const getShowSkeleton = ({ isFetching, isFetchingExpandedData, isPivot, hasGroupedData }) => isFetching || (isFetchingExpandedData && !isPivot && !hasGroupedData);
const getEntity = ({ vulnsAssetTable }) => (vulnsAssetTable ? 'vulnsAssets' : 'vulns');

const notGrouped = ({ groupBy }) => !groupBy;
const fieldOrder = (fieldKey) => ({ fields }) => fields[fieldKey]?.order;
// `fields.x?.visible && !(showVulnDetail && currentBreakpoint === 'second')`, same falsy values as legacy.
const visibleUnlessDetail = (fieldKey) => (ctx) => ctx.fields[fieldKey]?.visible && !isDetailExtended(ctx);
const minWidthProps = (fieldKey) => (rowInfo, { fields }) => ({ className: `min-wd-${fields[fieldKey]?.defaultMin}` });
const minWidthThemedProps = (fieldKey) => (rowInfo, { fields, theme }) => ({ className: `min-wd-${fields[fieldKey]?.defaultMin}`, style: { color: theme.text.tableVulnName } });
// eslint-disable-next-line react/display-name
const genericCell = (attrib, extraProps = {}) => (rowInfo, ctx) => <GenericCell showSkeleton={ getShowSkeleton(ctx) } rowInfo={ rowInfo } attrib={ attrib } { ...extraProps } />;

/**
 * Plain detail column: `fields[fieldKey]` drives visibility/order/widths, hidden while the detail
 * is open on the 'second' breakpoint, resizable only without group by.
 */
const detailColumn = (fieldKey, column) => ({
  visible: visibleUnlessDetail(fieldKey),
  resizable: notGrouped,
  ...fieldWidths(fieldKey, { groupAware: true }),
  order: fieldOrder(fieldKey),
  ...column
});

const renderIssueTracker = (rowInfo) => {
  if (isEmpty(rowInfo.original.issuetracker)) return null;
  let issueTracker = '';
  const issueTrackerJson = rowInfo.original.issuetracker;

  if (issueTrackerJson.whd) issueTracker = TOOL_NAME_SOLAR_WINDS;
  if (issueTrackerJson.gitlab) issueTracker = TOOL_NAME_GITLAB;
  if (issueTrackerJson.servicenow) issueTracker = TOOL_NAME_SERVICE_NOW;
  if (issueTrackerJson.mesd) issueTracker = TOOL_NAME_SERVICE_DESK;
  if (issueTrackerJson.jira) {
    return issueTrackerJson.jira.map((issue) => {
      const id = (issue.tool_id ?? issue.key)?.toUpperCase();

      return (
        <Link key={ id } target="_blank" href={ issue.url }>
          {id},{' '}
        </Link>
      );
    });
  }
  if (issueTrackerJson && issueTracker && issueTrackerJson[issueTracker].length) {
    return <Link target="_blank" href={ issueTrackerJson[issueTracker][0].url }>{issueTracker.toUpperCase()}</Link>;
  } else if (issueTrackerJson && issueTracker && issueTrackerJson[issueTracker]) {
    return <Link target="_blank" href={ issueTrackerJson[issueTracker].url }>{issueTracker.toUpperCase()}</Link>;
  }
  return null;
};

