// Custom attribute columns, appended after the base ones exactly like the legacy getColumns.
const getCustomFieldColumns = (ctx) => {
  const { customFields, fields } = ctx;
  if (!customFields) return [];

  return customFields.reduce((acc, cf) => {
    const key = `${cf.field_display_name}_custom`;
    const defaultFieldMeta = fields[cf.field_name];
    const fieldMeta = fields[key];

    if (!fieldMeta) return acc;

    const showCustom = fieldMeta.visible && !isDetailExtended(ctx);
    const defaultVisible = defaultFieldMeta?.visible;

    if (showCustom && (!defaultVisible || (defaultVisible && showCustom))) {
      acc.push({
        header: () => <div>{cf.field_display_name.toUpperCase()}</div>,
        id: key,
        accessor: row => row.custom_fields?.[cf.field_name] ?? '',
        visible: true,
        sortable: false,
        resizable: false,
        maxWidth: 200,
        minWidth: 200,
        order: fieldMeta.order,
        cell: (rowInfo) => <p>{rowInfo.value}</p>
      });
    }
    return acc;
  }, []);
};

