    id: 'group_by',
    accessor: 'group_by',
    resizable: true,

    maxWidth: ({ fields }) => fields.group_by?.maxWidth ?? 140,
    minWidth: ({ fields }) => fields.group_by?.minWidth ?? 120,
    width: ({ fields }) => fields.group_by?.defaultMin ?? 130,
    visible: ({ fields }) => fields.group_by?.visible ?? true,
