    minWidth: ({ fields }) => fields.vulnerabilities.minWidth,
    width: ({ fields }) => fields.vulnerabilities.defaultMin,
    visible: ({ fields }) => fields.vulnerabilities.visible,
    order: ({ fields }) => fields.vulnerabilities.order,
