const getSingleNameUpdateTarget = (state) => {
  const vulnsSelected = selectVulnsSelected(state);
  if (vulnsSelected.length === 1) return vulnsSelected[0];

  const vulnDetail = selectVulnDetail(state);
  return isEmpty(vulnDetail) ? null : vulnDetail;
};
const exploreRoutePattern = /^\/vulns\/[^/]+\/groups\/[^/]+\/?$/;
const isExploreGroupPath = (pathname = '') => exploreRoutePattern.test(pathname);
const resolveUpdateVulnOptions = (showNewUIOrOptions = false, options = {}) => {
  if (typeof showNewUIOrOptions === 'object' && showNewUIOrOptions !== null) {
    return {
      showNewUI: false,
      options: showNewUIOrOptions
    };
  }

  return {
    showNewUI: showNewUIOrOptions === true,
    options
  };
};

