export function downloadVulns (exportAllData) {
  return async (dispatch, getState) => {
    const workspace = selectCurrentWorkspace(getState());
    const fields = selectManageFields(getState());
    const columnsIncluded = getExportCsvColumns(fields, VALID_COLUMNS);
    const state = getState();
    let advancedFilterQueryParam = [];
    try {
      if (exportAllData) advancedFilterQueryParam = selectAdvancedFilterQueryParam(state, 'vulns', true);
      else advancedFilterQueryParam = selectAdvancedFilterQueryParam(state, 'vulns', true, columnsIncluded);
    } catch (e) {
      dispatch(setFilterError('vulns', 'Syntax error. Please try again. For further help check our documentation'));
      return dispatch(setVulnsFilterError());
    }

    const hasAdvancedFilter = advancedFilterQueryParam.filters.length > 0;
    let standardQueryParam = [];
    if (exportAllData) standardQueryParam = selectQueryParam('vulns', state, true);
    else standardQueryParam = selectQueryParam('vulns', state, true, columnsIncluded);
    const queryParam = hasAdvancedFilter ? advancedFilterQueryParam : standardQueryParam;

    try {
      dispatch({ type: types.EXPORT_CSV_MANAGE_REQUEST });
      let response = '';
      if (exportAllData) response = await api.manage.exportCSVAllVulns(workspace, queryParam);
      else response = await api.manage.exportCSVFiltered(workspace, queryParam);
      dispatch(exportCsv(response));
    } catch (err) {
      dispatch({ type: types.EXPORT_CSV_MANAGE_FAILURE });
    }

    return dispatch({ type: types.EXPORT_CSV_MANAGE_SUCCESS });
  };
}

