// getTopHosts() is the single source for "top hosts" data — it used to be
// duplicated as fetchTopAssetsByVulns() (same endpoint, same cache, a
// module-level mutex to dedup the two). Both the legacy TopHosts widget and
// the FindingsByAsset widget now call this one action directly instead of
// relying on a parent container to prefetch it for them.
// The isFetchingTopHosts flag below is enough to dedupe two widgets mounting
// together without any extra module-level lock: dispatch() runs the reducer
// synchronously, so the flag is already true in the store by the time a
// second, later call reads getState() — even with no `await` in between.
export function getTopHosts () {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const workspace = selectCurrentWorkspace(state);
      const cache = state.dashboard?.cache?.topAssets;
      const now = Date.now();
      const TTL = 5 * 60 * 1000;

      if (state.dashboard?.isFetchingTopHosts) return Promise.resolve();
      if (cache && cache.workspace === workspace && (now - cache.timestamp) < TTL) {
        return Promise.resolve();
      }

      dispatch({ type: GET_TOP_HOSTS });
      const response = await api.dashboard.getTopHostsDashboard(workspace);
      return dispatch({ type: GET_TOP_HOSTS_SUCCEED_DASHBOARD, data: response, cache: { workspace, timestamp: now, ttl: TTL } });
    } catch (e) {
      return dispatch({ type: GET_TOP_HOSTS_FAILURE_DASHBOARD, error: e.message || 'An error has occurred.' });
    }
  };
}

