export function onGetVulnsByStatusFail (e) {
  return (dispatch) => {
    dispatch({ type: GET_VULNS_BY_STATUS_FAILURE, error: e });
  };
}

export function getVulnsCountByStatus (filterParams = '') {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const workspace = selectCurrentWorkspace(state);
      const { isFetchingVulnsByStatus } = state.dashboard;
      const cache = state.dashboard?.cache?.vulnCountByStatus;
      const now = Date.now();
      const TTL = 5 * 60 * 1000;

      if (isFetchingVulnsByStatus) return;

      if (cache && cache.workspace === workspace && cache.filterParams === filterParams && cache.timestamp && (now - cache.timestamp) < TTL) {
        return Promise.resolve();
      }

      dispatch({ type: GET_VULNS_BY_STATUS_REQUEST });

      const response = await api.dashboard.getVulnsCountByStatus(workspace, filterParams);
      const hasData = response?.groups?.length > 0;
      return dispatch({ type: GET_VULNS_BY_STATUS_SUCCESS, data: response, cache: hasData ? { timestamp: now, workspace, filterParams } : undefined });
    } catch (e) {
      return dispatch(onGetVulnsByStatusFail(get(e, 'message', 'Failed to obtain Vuln count by Status.')));
    }
  };
}

