export function getVulnsCountBySeverity (filterParams = '') {
  return async (dispatch, getState) => {
    try {
      const state = getState();
      const workspace = selectCurrentWorkspace(state);
      const { isFetchingVulnsBySeverity } = state.dashboard;
      const cache = state.dashboard?.cache?.vulnCountBySeverity;
      const now = Date.now();
      const TTL = 5 * 60 * 1000;

      if (isFetchingVulnsBySeverity) return Promise.resolve();

      // Remediation and BySeverity both need this data and each fetch it on
      // their own mount (no widget waits on a sibling for it) — the cache key
      // includes filterParams so both only dedupe into one request when they
      // actually agree on the same confirmed/closed filters.
      if (cache && cache.workspace === workspace && cache.filterParams === filterParams && (now - cache.timestamp) < TTL) {
        return Promise.resolve();
      }

      dispatch({ type: GET_VULNS_BY_SEVERITY_REQUEST });
      const response = await api.dashboard.getVulnsCountBySeverity(workspace, filterParams);
      const hasData = response?.groups?.length > 0;
      return dispatch({ type: GET_VULNS_BY_SEVERITY_SUCCESS, data: response, cache: hasData ? { workspace, filterParams, timestamp: now } : undefined });
    } catch (e) {
      return dispatch(onGetVulnsBySeverityFail(get(e, 'message', 'Failed to obtain Vuln count by Severity.')));
    }
  };
}

