const fetching = () => ({ type: GROUP_VULNS_FETCHING });
const fail = (e) => ({
  type: GROUP_VULNS_FAIL,
  message: get(e, 'message', 'There was an error, please try again')
});

export const clearError = () => ({ type: GROUP_VULNS_CLEAR_ERROR });

const normalizeEntity = (entity) => entity || 'vulns';
const DEFAULT_EXPLORE_PAGE = 1;
const DEFAULT_EXPLORE_PAGE_SIZE = 50;

const normalizePositiveInteger = (value, fallback = 1) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  const normalized = Math.trunc(parsed);
  return normalized >= 1 ? normalized : fallback;
};

const getExplorePageSize = (state) => normalizePositiveInteger(
  selectRowsPerPage('vulns', state),
  DEFAULT_EXPLORE_PAGE_SIZE
);

const refreshList = (entity) => async (dispatch, getState) => {
  const state = getState();

  const currentAsset = selectCurrentHost(state);
  const hostIp = get(currentAsset, 'ip', '');

  const refresh = {
    vulns: () => dispatch(newGetVulns()),
    vulnsAssets: () => dispatch(getVulns(hostIp)),
    vulnsGeneral: () => dispatch(getVulnsGeneral())
  };

  const key = normalizeEntity(entity);
  if (refresh[key]) await refresh[key]();

  await dispatch(getVulnsCountInWs());
  await dispatch(getHostsCountInWs());
};

const BACKEND_INVALID_GROUPING_MESSAGE = 'No valid vulnerabilities found. They may not belong to this workspace or are already part of a group.';

const getRowValue = (row) => row?.value ?? row;
const isGrouped = (row) => {
  const value = getRowValue(row);
  return value?.is_automatic !== null && typeof value?.is_automatic !== 'undefined';
};
const isGroupHeader = (row) => {
  const value = getRowValue(row);
  return isGrouped(row) && value?.is_main === true;
};
const isAutomaticGroup = (row) => {
  const value = getRowValue(row);
  return isGroupHeader(row) && value?.is_automatic === true;
};
const exploreRoutePattern = /^\/vulns\/([^/]+)\/groups\/([^/]+)$/;

const getGroupIdFromPath = (pathname) => {
  const match = (pathname || '').match(exploreRoutePattern);
  if (!match) return null;
  const routeGroupId = match[2];
  return routeGroupId === 'new' ? null : routeGroupId;
};

const getRefreshGroupId = (state) => {
  const pathname = selectPathname(state);
  const routeGroupId = getGroupIdFromPath(pathname);
  if (routeGroupId !== null) return routeGroupId;
  const payload = selectExploreGroupPayload(state);
  const payloadGroupId = get(payload, 'groupId', get(payload, 'groupHeaderId', null));
  return payloadGroupId;
};

/**
 * CREATE MANUAL GROUP
 * @param {string} entity - 'vulns' | 'vulnsAssets' | 'vulnsGeneral'
 * @param {number[]} groupIds - ids selected to create the group
 * @param {string} groupTitle - group name
 */
export const createManualGroup = (entity, groupIds, groupTitle) => async (dispatch, getState) => {
  try {
    dispatch(fetching());

    const ws = selectCurrentWorkspace(getState());
    const payload = { groupIds, groupTitle };

    const res = await api.groupVulns.createManualGroup(ws, payload);

    dispatch({ type: GROUP_VULNS_CREATE_SUCCESS });
    await dispatch(refreshList(entity));

    return res;
  } catch (e) {
    dispatch(fail(e));
    return null;
  }
};

