export const ManualGroupingErrors = {
  MIN_SELECTION: 'MIN_SELECTION',
  MULTIPLE_GROUPS: 'MULTIPLE_GROUPS',
  AUTOMATIC_GROUP: 'AUTOMATIC_GROUP'
};

export const getManualGroupingBlocker = (vulnsSelected = []) => {
  const selected = vulnsSelected ?? [];
  const selectedGroupHeaders = selected.filter(isGroupHeader);

  if (selected.length < 2) {
    return {
      code: ManualGroupingErrors.MIN_SELECTION,
      title: 'Manual Grouping',
      description: 'Please select two or more vulnerabilities to create a manual grouping.'
    };
  }

  if (selectedGroupHeaders.length > 1) {
    return {
      code: ManualGroupingErrors.MULTIPLE_GROUPS,
      title: 'Manual Grouping',
      description: BACKEND_INVALID_GROUPING_MESSAGE
    };
  }

  if (selectedGroupHeaders.length === 1 && isAutomaticGroup(selectedGroupHeaders[0])) {
    return {
      code: ManualGroupingErrors.AUTOMATIC_GROUP,
      title: 'Manual Grouping',
      description: 'Only manual groups can be modified.'
    };
  }

  return null;
};

export const refreshExploreGroupHosts = ({ page, pageSize } = {}) => async (dispatch, getState) => {
  const state = getState();
  const pathname = selectPathname(state);
  const isExploreRoute = exploreRoutePattern.test(pathname || '');
  const isExploreOpen = selectIsExploreGroupOpen(state);

  if (!isExploreRoute && !isExploreOpen) return null;

  const ws = selectCurrentWorkspace(state);
  const groupId = getRefreshGroupId(state);
  const currentPage = selectExploreGroupHostsPage(state);
  const resolvedPage = normalizePositiveInteger(page, currentPage);
  const resolvedPageSize = normalizePositiveInteger(pageSize, getExplorePageSize(state));
  if (!ws) return null;

  try {
    dispatch({ type: GROUP_VULNS_EXPLORE_HOSTS_FETCHING });

    const showGroupHostsPayload = (groupId === null || typeof groupId === 'undefined')
      ? { page: resolvedPage, pageSize: resolvedPageSize }
      : { groupId, page: resolvedPage, pageSize: resolvedPageSize };
    const res = await api.groupVulns.showGroupHosts(ws, showGroupHostsPayload);
    const hosts = get(res, 'rows', get(res, 'hosts', get(res, 'results', get(res, 'data', []))));
    const hostsArray = Array.isArray(hosts) ? hosts : [];
    const hostCount = get(res, 'count', hostsArray.length);
    dispatch({
      type: GROUP_VULNS_EXPLORE_HOSTS_SUCCESS,
      hosts: hostsArray,
      meta: {
        ws,
        groupId,
        hostCount,
        page: resolvedPage,
        pageSize: resolvedPageSize
      }
    });
    return res;
  } catch (e) {
    dispatch({ type: GROUP_VULNS_EXPLORE_HOSTS_FAIL });
    dispatch(fail(e));
    return null;
  }
};

