export const exploreGroup = (payload) => (dispatch, getState) => {
  const ws = selectCurrentWorkspace(getState());
  const groupId = get(payload, 'groupId', null);
  const groupHeaderId = get(payload, 'groupHeaderId', null);

  // Debug aid: inspect from browser console via window.__lastExploreGroupPayload
  if (typeof window !== 'undefined') window.__lastExploreGroupPayload = payload;
  // eslint-disable-next-line no-console
  console.warn('[GroupVulns] exploreGroup payload:', payload);

  dispatch({
    type: GROUP_VULNS_EXPLORE_OPEN,
    payload
  });

  if (ws) {
    let targetGroupId = 'new';
    if (groupId !== null && typeof groupId !== 'undefined') targetGroupId = groupId;
    else if (groupHeaderId !== null && typeof groupHeaderId !== 'undefined') targetGroupId = groupHeaderId;
    dispatch(redirect(`/vulns/${ws}/groups/${targetGroupId}`));
  }
};

