const updateExploreHostTagsLocally = (hostIds, tagsToAdd, tagsToRemove) => ({
  type: GROUP_VULNS_EXPLORE_UPDATE_HOST_TAGS,
  hostIds,
  tagsToAdd,
  tagsToRemove
});

const updateExploreServiceTagsLocally = (serviceIds, tagsToAdd, tagsToRemove) => ({
  type: GROUP_VULNS_EXPLORE_UPDATE_SERVICE_TAGS,
  serviceIds,
  tagsToAdd,
  tagsToRemove
});

const applyExploreHostTags = (tagsToAdd, tagsToRemove) => async (dispatch, getState) => {
  const state = getState();
  const ws = selectCurrentWorkspace(state);
  const ids = state.groupVulns?.explore?.selectedHostIds ?? [];
  if (!ws || !ids.length) return;
  const numericIds = ids.map(Number).filter((n) => !Number.isNaN(n));
  dispatch(updateExploreHostTagsLocally(ids, tagsToAdd, tagsToRemove));
  try {
    await api.host.setHostsTags(ws, { host_ids: numericIds, tags_to_add: tagsToAdd, tags_to_remove: tagsToRemove });
    dispatch(getTags());
    dispatch(getHostsTags());
  } catch (e) {
    dispatch(updateExploreHostTagsLocally(ids, tagsToRemove, tagsToAdd));
  }
};

const applyExploreServiceTags = (tagsToAdd, tagsToRemove) => async (dispatch, getState) => {
  const state = getState();
  const ws = selectCurrentWorkspace(state);
  const ids = state.groupVulns?.explore?.selectedServiceIds ?? [];
  if (!ws || !ids.length) return;
  const numericIds = ids.map(Number).filter((n) => !Number.isNaN(n));
  dispatch(updateExploreServiceTagsLocally(ids, tagsToAdd, tagsToRemove));
  try {
    await api.service.setServicesTags(ws, { service_ids: numericIds, tags_to_add: tagsToAdd, tags_to_remove: tagsToRemove });
    dispatch(getTags());
    dispatch(getHostsTags());
    dispatch(getServicesTags());
  } catch (e) {
    dispatch(updateExploreServiceTagsLocally(ids, tagsToRemove, tagsToAdd));
  }
};

export const addExploreGroupHostTag = (tag) => applyExploreHostTags([tag], []);
export const removeExploreGroupHostTag = (tag) => applyExploreHostTags([], [tag]);
export const setExploreGroupHostNewTags = (newTags) => applyExploreHostTags(newTags, []);

export const addExploreGroupServiceTag = (tag) => applyExploreServiceTags([tag], []);
export const removeExploreGroupServiceTag = (tag) => applyExploreServiceTags([], [tag]);
export const setExploreGroupServiceNewTags = (newTags) => applyExploreServiceTags(newTags, []);

export const deleteExploreGroupSelectedHosts = () => async (dispatch, getState) => {
  const state = getState();
  const ws = selectCurrentWorkspace(state);
  const ids = state.groupVulns?.explore?.selectedHostIds ?? [];
  if (!ws || !ids.length) return;
  const numericIds = ids.map(Number).filter((n) => !Number.isNaN(n));
  try {
    await api.host.deleteHost(ws, numericIds);
    dispatch({ type: GROUP_VULNS_EXPLORE_HOSTS_DELETE_SUCCESS, hostIds: ids });
    dispatch(refreshExploreGroupHosts());
  } catch (e) {
    dispatch(fail(e));
  }
};

