export const showGroupServices = async (workspace, {
  groupId,
  page,
  pageSize
} = {}) => {
  const params = {};

  if (groupId !== null && typeof groupId !== 'undefined') {
    params.group_id = groupId;
  }
  if (Number.isFinite(page) && page >= 1) {
    params.page = Math.trunc(page);
  }
  if (Number.isFinite(pageSize) && pageSize >= 1) {
    params.page_size = Math.trunc(pageSize);
  }

  try {
    return await fetchApi(`ws/${workspace}/services`, { method: 'GET', params: Object.keys(params).length ? params : undefined, version: 'v3' });
  } catch (e) {
    return mockGroupServicesResponse;
  }
};
