const mergeHostDetailData = (baseHost = {}, fetchedHost = {}) => ({
  ...baseHost,
  ...fetchedHost,
  id: fetchedHost.id ?? baseHost.id,
  _id: fetchedHost._id ?? baseHost._id,
  name: fetchedHost.name ?? baseHost.name ?? '',
  owner: fetchedHost.owner ?? baseHost.owner ?? '',
  service_summaries: fetchedHost.service_summaries ?? baseHost.service_summaries ?? [],
  services_status: fetchedHost.services_status ?? baseHost.services_status ?? [],
  service_statuses: fetchedHost.service_statuses ?? baseHost.service_statuses ?? [],
  service_ports: fetchedHost.service_ports ?? baseHost.service_ports ?? [],
  services: fetchedHost.services ?? baseHost.services ?? null,
  open_services: fetchedHost.open_services ?? baseHost.open_services ?? null,
  severity_counts: fetchedHost.severity_counts ?? baseHost.severity_counts ?? null,
  vulns: fetchedHost.vulns ?? baseHost.vulns ?? null,
  workspace_name: fetchedHost.workspace_name ?? baseHost.workspace_name ?? ''
});

const exploreGroupRoutePattern = /^\/vulns\/[^/]+\/groups\/[^/]+$/;
const hostServiceDetailRoutePattern = /^\/host\/[^/]+\/[^/]+\/services\/([^/]+)$/;

const isExploreGroupContext = (state) =>
  selectIsExploreGroupOpen(state) || exploreGroupRoutePattern.test(selectPathname(state) || '');

const canKeepServiceDetailOpen = (state, serviceId) => {
  const pathname = selectPathname(state) || '';
  if (pathname.startsWith('/manage/') || exploreGroupRoutePattern.test(pathname)) return true;

  const serviceDetailRouteMatch = pathname.match(hostServiceDetailRoutePattern);
  return !!serviceDetailRouteMatch && String(serviceDetailRouteMatch[1]) === String(serviceId);
};

const getVulnId = (vuln = {}) => {
  const id = get(vuln, '_id', undefined);
  if (id !== null && typeof id !== 'undefined') return id;
  return get(vuln, 'id', null);
};

const normalizeVuln = (vuln = {}) => {
  const id = getVulnId(vuln);
  if (id === null || typeof id === 'undefined') return vuln;
  const currentId = get(vuln, 'id', undefined);
  const currentUnderscoreId = get(vuln, '_id', undefined);

  return {
    ...vuln,
    id: currentId !== null && typeof currentId !== 'undefined' ? currentId : id,
    _id: currentUnderscoreId !== null && typeof currentUnderscoreId !== 'undefined' ? currentUnderscoreId : id
  };
};

const normalizeVulnRow = (vuln) => normalizeVuln(get(vuln, 'value', vuln));

const normalizeVulnsResponse = (data) => get(data, 'vulnerabilities', []).map(normalizeVulnRow);

const getSingleNameUpdateTarget = (state) => {
  const vulnsSelected = selectSelected('vulns', state);
  if (vulnsSelected.length === 1) return vulnsSelected[0];

  const vulnDetail = selectDetail('vulns', state);
  return isEmpty(vulnDetail) ? null : vulnDetail;
};

