export function updateVulnFromAsset (vulnBefore, field, value, options = {}) {
  return async (dispatch, getState) => {
    const workspaceSelected = selectCurrentWorkspace(getState());
    const vulnsList = selectVulns(getState());
    const vulnsCount = selectCount('vulns', getState());
    const groupingStartTimestamp = Date.now();
    const vulnId = getVulnId(vulnBefore);
    let newVuln = normalizeVuln({ ...vulnBefore });
    set(newVuln, field, value);
    try {
      if (vulnId === null || typeof vulnId === 'undefined') throw new Error('Vulnerability id not found.');

      const newList = [...vulnsList];
      let newRefs = [];
      let rawResponse = null;
      if (field === 'refs') {
        newRefs = value.map((ref) => ({ name: ref, type: 'other' }));
        rawResponse = await api.manage.updateVuln(workspaceSelected, { _id: vulnId, refs: newRefs });
      } else {
        rawResponse = await api.manage.updateVuln(workspaceSelected, { _id: vulnId, [field]: value });
      }
      newVuln = normalizeVuln(extractUpdatedVulnerabilityFromResponse(rawResponse, newVuln));
      const commandId = extractCommandIdFromResponse(rawResponse);
      const isGrouping = extractIsGroupingFromResponse(rawResponse) === true;
      const groupingCommand = options.enqueueGroupingFromResponse === false
        ? null
        : buildGroupingCommandFromResponse(rawResponse, {
          workspaceName: workspaceSelected,
          groupingStartTimestamp,
          commandId
        });
      if (field === 'name') {
        logGroupingDebug('name_edit_patch_response', {
          source: 'assetDetail.updateVulnFromAsset',
          workspaceName: workspaceSelected,
          vulnerabilityId: vulnId,
          commandId
        });
      }

      const newVulnId = getVulnId(newVuln);
      const index = vulnsList.findIndex((x) => getVulnId(x) === newVulnId);
      if (index > -1) newList[index] = newVuln;

      dispatch({ type: types.UPDATE_VULN_ASSET_PREVIEW_SUCCESS, data: newList, vulnsCount, vuln: newVuln });
      if (groupingCommand) dispatch(enqueueCommand(groupingCommand));
      if (field === 'confirmed') dispatch(getVulnsCountInWs());
      if (['status', 'severity', 'confirmed'].includes(field)) dispatch(refreshDashboard());
      return {
        ok: true,
        updatedVuln: newVuln,
        commandId,
        isGrouping,
        response: rawResponse,
        groupingEnqueued: Boolean(groupingCommand)
      };
    } catch (e) {
      dispatch({ type: types.UPDATE_VULN_ASSET_PREVIEW_FAIL, errorMessage: e.message });
      return {
        ok: false,
        error: e
      };
    }
  };
}

