export function updateService (serviceId, valueObj) {
  return async (dispatch, getState) => {
    const state = getState();
    const workspaceSelected = selectCurrentWorkspace(state);
    const serviceList = selectServices(state);
    const serviceCount = selectCount('services', state);
    const serviceDetailId = selectServiceId(state);
    try {
      const newService = await api.service.updateService(workspaceSelected, { id: serviceId, ...valueObj });
      const index = serviceList.findIndex((x) => String(serviceId) === String(x.id) || String(serviceId) === String(x._id));
      const updatedServiceList = [...serviceList];
      if (index > -1) updatedServiceList[index] = { ...newService };

      dispatch({ type: types.ASSET_DETAIL_UPDATE_SERVICE_SUCCESS, data: updatedServiceList, serviceCount });
      const newServiceId = get(newService, '_id', get(newService, 'id', serviceId));
      if (serviceDetailId && String(newServiceId) === String(serviceDetailId) && canKeepServiceDetailOpen(getState(), newServiceId)) {
        dispatch(showDetail('services', newService));
      }

      if (isExploreGroupContext(getState())) await dispatch(refreshExploreGroupServices());
    } catch (e) {
      dispatch({ type: types.UPDATE_SERVICE_ASSET_FAIL, errorMessage: getServiceErrorMessage(e) });
    }
  };
}

