export const setContextMenuFilter = (filterKey, selectedVuln) => (dispatch) => {
  const newFilter = contextMenufilteringFunctions[filterKey](selectedVuln);
  if (filterKey === 'tags') {
    dispatch(clearFilters('vulnsGeneral'));
    newFilter.forEach((tagFilter) => {
      dispatch(addFilter('vulnsGeneral', tagFilter));
    });
  } else if (newFilter) dispatch(setFilter('vulnsGeneral', newFilter));
  dispatch(getVulnsGeneral());
};

