export const bulkUpdateVulns = () => async (dispatch, getState) => {
  const state = getState();
  const field = selectModalBulkUpdateField(state);
  const value = selectModalBulkUpdateValue(state);
  const singleNameTarget = field === 'name' ? getSingleNameUpdateTarget(state) : null;
  const normalizedNameValue = field === 'name' ? normalizeVulnerabilityName(value) : value;

  if (field === 'name' && singleNameTarget && normalizeVulnerabilityName(singleNameTarget.name) === normalizedNameValue) {
    dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE));
    dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE_CONFIRMATION));
    dispatch({ type: types.RESET_ERROR_VALUE });
    dispatch({ type: types.GENERAL_MANAGE_BULK_UPDATE_FINISHED });
    return;
  }

  dispatch({ type: types.GENERAL_MANAGE_CONFIRMATION_CHANGE_START });

  try {
    const vulnsList = selectVulns(state);
    const vulnsSelected = selectVulnsSelected(state);
    const vulnDetail = selectVulnDetail(state);
    const selectAll = selectSelectAll(state);
    const vulnIDs = vulnsSelected.map(getVulnId).filter((id) => id !== null && typeof id !== 'undefined');
    const customAttribute = selectBulkUpdateCustomAttribute(state);
    const customAttributeType = get(customAttribute, 'field_type', '');
    const customAttributeFieldName = get(customAttribute, 'field_name', '');
    const customAttributeValue = ((customAttributeType === 'choice') && (value === '(Empty)')) ? '' : value;

    const advancedFilterQueryParam = selectAdvancedFilterQueryParam(state, 'vulnsGeneral');
    const hasAdvancedFilter = advancedFilterQueryParam.filters.length > 0;
    const standardQueryParam = selectQueryParam('vulnsGeneral', state);
    const queryParam = hasAdvancedFilter ? advancedFilterQueryParam : standardQueryParam;

    let data = {};

    if (field === 'references') data = { refs: value.map((v) => ({ name: v, type: 'other' })) };
    else if (field === 'policy violations') data = { policyviolations: value };
    else if (field === 'description') data = { description: value, desc: value };
    else if (field === 'impact') data = getImpactData(value, vulnsSelected);
    else if (field === 'custom_fields' && (vulnsSelected?.length > 1)) data = { custom_fields: { [customAttributeFieldName]: customAttributeValue } };
    else if (field === 'custom_fields' && (vulnsSelected?.length === 1)) data = { custom_fields: { ...vulnsSelected[0].custom_fields, [customAttributeFieldName]: customAttributeValue } };
    else data = { [field]: field === 'name' ? normalizedNameValue : value };

    const isDetailVulnSelected = vulnsSelected.some((selectedVuln) => !isEmpty(vulnDetail) && sameVulnId(selectedVuln, vulnDetail));

    if (selectAll) {
      await api.vulnsGeneral.updateAllVulns({ filters: queryParam.filters }, data);

      const currentUser = selectUserName(state);
      const patchStatus = (vuln) => field === 'status'
        ? applyOptimisticStatusHistory({ ...vuln, ...data }, value, currentUser)
        : { ...vuln, ...data };
      const updatedVulnsList = vulnsList.map(patchStatus);
      const updatedSelectedVulns = vulnsSelected.map(patchStatus);
      const updatedVulnDetail = isDetailVulnSelected ? patchStatus(vulnDetail) : { ...vulnDetail };

      dispatch(refreshVulnsList(updatedVulnsList, updatedSelectedVulns, updatedVulnDetail));
    } else if (field === 'name' && singleNameTarget) {
      const workspaceName = get(singleNameTarget, 'workspace_name', '');
      const groupingStartTimestamp = Date.now();
      const response = await api.manage.updateVuln(workspaceName, {
        _id: singleNameTarget._id,
        name: normalizedNameValue
      });

      const updatedVuln = extractUpdatedVulnerabilityFromResponse(response, {
        ...singleNameTarget,
        name: normalizedNameValue
      });
      const commandId = extractCommandIdFromResponse(response);
      const isGroupingFromResponse = extractIsGroupingFromResponse(response);
      const workspaces = selectWorkspaces(state);
      const shouldEnqueueGrouping = shouldTreatFieldUpdateAsGrouping({
        workspaceName,
        workspaces,
        field: 'name',
        commandId,
        isGrouping: isGroupingFromResponse
      });
      let groupingDecisionSource = 'response.missing';
      if (isGroupingFromResponse === true) groupingDecisionSource = 'response.is_grouping';
      else if (shouldEnqueueGrouping) groupingDecisionSource = 'workspace.group_by_fallback';
      logGroupingDebug('name_edit_patch_response', {
        source: 'manageGeneral.bulkUpdate.singleName',
        workspaceName,
        vulnerabilityId: singleNameTarget?._id,
        commandId,
        isGroupingFromResponse,
        shouldEnqueueGrouping,
        groupingDecisionSource
      });

      dispatch(vulnPreviewEditSuccedCallback(singleNameTarget, updatedVuln));
      if (shouldEnqueueGrouping) {
        logGroupingDebug('name_edit_grouping_enqueued', {
          source: 'manageGeneral.bulkUpdate.singleName',
          workspaceName,
          commandId
        });
        dispatch(enqueueCommand({
          command_id: commandId ?? null,
          commandType: 'grouping',
          name: workspaceName,
          fileType: 'grouping',
          isGrouping: true,
          groupingStartTimestamp,
          error: false,
          finished: false
        }));
        dispatch(redirectToVulnerabilities());
      }

      dispatch({ type: types.GENERAL_MANAGE_SET_BULK_UPDATE_SUCCESS });
    } else {
      const payload = { ids: vulnIDs, ...data };

      await api.vulnsGeneral.updateVulns(payload);

      const currentUser = selectUserName(state);
      const patchStatus = (vuln) => field === 'status'
        ? applyOptimisticStatusHistory({ ...vuln, ...data }, value, currentUser)
        : { ...vuln, ...data };
      const updatedVulnsList = vulnsList.map((vuln) => {
        if (!vulnsSelected.some((selectedVuln) => sameVulnId(selectedVuln, vuln))) return vuln;
        return patchStatus(vuln);
      });
      const updatedSelectedVulns = vulnsSelected.map(patchStatus);
      const updatedVulnDetail = isDetailVulnSelected ? patchStatus(vulnDetail) : { ...vulnDetail };

      dispatch({ type: types.GENERAL_MANAGE_SET_BULK_UPDATE_SUCCESS });
      dispatch(refreshVulnsList(updatedVulnsList, updatedSelectedVulns, updatedVulnDetail));
    }

    dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE));
    dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE_CONFIRMATION));
    dispatch({ type: types.GENERAL_MANAGE_BULK_UPDATE_FINISHED });
  } catch (e) {
    dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE_CONFIRMATION));
    if (field === 'name') dispatch({ type: types.SET_ERROR_MESSAGE, errorMessage: getVulnerabilityNameErrorMessage(e) });
    else {
      dispatch({ type: types.GENERAL_MANAGE_FAIL, errorMessage: e.message || 'An error occured while updating vulns' });
      dispatch(closeModal(MODAL_MANAGE_BULK_UPDATE));
    }
  }
};

