function vulnPreviewEditSuccedCallback (vulnBefore, vulnAfter) {
  return (dispatch, getState) => {
    const groupBy = selectGroupByField('vulnsGeneral', getState());
    const vulnsList = selectVulns(getState());

    if (groupBy) {
      // se actualiza la tabla agrupada
      const indexGroupDataAfter = vulnsList.findIndex((x) => x[groupBy] === vulnAfter[groupBy]);
      const groupDataAfter = vulnsList[indexGroupDataAfter].groupData || [];
      const indexVulnAfter = groupDataAfter.findIndex((x) => sameVulnId(x, vulnAfter));
      if (indexVulnAfter < 0) { // no lo encontro, lo borro
        const indexGroupDataBefore = vulnsList.findIndex((x) => x[groupBy] === vulnBefore[groupBy]);
        const groupDataBefore = vulnsList[indexGroupDataBefore].groupData || {};
        const indexVulnBefore = groupDataBefore.findIndex((x) => sameVulnId(x, vulnAfter));
        // lo quito del grupo.
        vulnsList[indexGroupDataBefore].groupData.splice(indexVulnBefore, 1);
        // eslint-disable-next-line no-negated-condition
        if (!vulnsList[indexGroupDataAfter].groupData) vulnsList[indexGroupDataAfter].count += 1;
        else vulnsList[indexGroupDataAfter].groupData.push(vulnAfter);
      } else {
        vulnsList[indexGroupDataAfter].groupData[indexVulnAfter] = vulnAfter;
      }
    } else {
      // se actualiza la tabla
      const index = vulnsList.findIndex((x) => sameVulnId(x, vulnAfter));
      vulnsList[index] = vulnAfter;
    }

    dispatch({ type: types.GENERAL_MANAGE_UPDATE_PREVIEW_SUCCESS, vuln: vulnAfter, vulnsList });
  };
}

function vulnPreviewEditErrorCallback (error) {
  return (dispatch) => {
    dispatch({ type: types.GENERAL_MANAGE_UPDATE_PREVIEW_FAILURE, error: error.message || 'An error has occurred' });
  };
}

export const updateVulnGeneral = (vulnBefore, field, value, options = {}) => async (dispatch, getState) => {
  const workspace = get(vulnBefore, 'workspace_name', '');
  const groupingStartTimestamp = Date.now();
  let vulnAfter = { ...vulnBefore };
  set(vulnAfter, field, value);

  try {
    let newRefs = [];
    let rawResponse = null;
    if (field === 'refs') {
      newRefs = value.map((ref) => ({ name: ref, type: 'other' }));
      rawResponse = await api.manage.updateVuln(workspace, { _id: vulnBefore._id, refs: newRefs });
    } else {
      rawResponse = await api.manage.updateVuln(workspace, { _id: vulnBefore._id, [field]: value });
    }
    vulnAfter = extractUpdatedVulnerabilityFromResponse(rawResponse, vulnAfter);

    if (field === 'status') {
      vulnAfter = applyOptimisticStatusHistory(vulnAfter, value, selectUserName(getState()), vulnBefore.status_history);
    }

    const commandId = extractCommandIdFromResponse(rawResponse);
    const isGrouping = extractIsGroupingFromResponse(rawResponse) === true;
    const groupingCommand = options.enqueueGroupingFromResponse === false
      ? null
      : buildGroupingCommandFromResponse(rawResponse, {
        workspaceName: workspace,
        groupingStartTimestamp,
        commandId
      });
    if (field === 'name') {
      logGroupingDebug('name_edit_patch_response', {
        source: 'manageGeneral.updateVulnGeneral',
        workspaceName: workspace,
        vulnerabilityId: vulnBefore?._id,
        commandId
      });
    }

    dispatch(vulnPreviewEditSuccedCallback(vulnBefore, vulnAfter));
    if (groupingCommand) dispatch(enqueueCommand(groupingCommand));
    return {
      ok: true,
      updatedVuln: vulnAfter,
      commandId,
      isGrouping,
      response: rawResponse,
      groupingEnqueued: Boolean(groupingCommand)
    };
  } catch (error) {
    dispatch(vulnPreviewEditErrorCallback(error));
    return {
      ok: false,
      error
    };
  }
};

