import fetchApi from 'services/api/connector';

export const fetchLatestTags = (workspace) => fetchApi(`ws/${workspace}/tags?page=0&page_size=5&sort=date&sort_dir=desc`);

export const fetchLatestComments = (workspace) => fetchApi(`ws/${workspace}/comment/filter?q=${JSON.stringify({ limit: 5, offset: 0, order_by: [{ field: 'create_date', direction: 'desc' }], filters: [] })}`);

export const fetchLatestVulns = (ws, confirmed) => fetchApi(`ws/${ws}/vulns?page=0&page_size=5&sort=date&sort_dir=desc${confirmed ? '&confirmed=1' : ''}`);

export const getVulnsCountByStatus = (ws, params = '') => fetchApi(`ws/${ws}/vulns/count?group_by=status${params}`);

export const getVulnsCountBySeverity = (ws, params = '') => fetchApi(`ws/${ws}/vulns/count?group_by=severity${params}`);

export const getTopHostsDashboard = (ws, pageSize = 10) => fetchApi(`ws/${ws}/hosts?page=1&page_size=${pageSize}`);

export const getVulnsCountByMultiWs = (ws, param) => fetchApi(`ws/${ws}/vulns/count_multi_workspace?group_by=severity&workspaces=${ws}${param}`);

export const getTopServicesByName = (ws) => fetchApi(`ws/${ws}/services/count?group_by=name`);

export const getVulnsTimeline = (ws) => fetchApi(`ws/${ws}/vulns/timeline`);

export const getActivitiesList = (ws, page) => fetchApi(`ws/${ws}/activities?page_size=16&page=${page}`);

export const COMMAND_HISTORY_PAGE_SIZE = 16;

export const getCommandHistory = (ws, page) => fetchApi(`ws/${ws}/commands?page_size=${COMMAND_HISTORY_PAGE_SIZE}&page=${page}`);

