// TODO: Reemplazar stub por API real cuando backend implemente /api/ws/{ws}/vulns/timeline
export const fetchFoundVsClosedTimeline = (workspaceId, days = 15) => {
  const timeline = [];
  const today = new Date();
  for (let i = days - 1; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    timeline.push({
      date: date.toISOString().split('T')[0],
      found_count: (i % 10) + 1,
      closed_count: i % 5
    });
  }
  return Promise.resolve({ timeline });
};

